Find the volume of this rectangular prism. The diagram is not to scale.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (A) at (0,0);
\coordinate (B) at (3.5,0);
\coordinate (C) at (3.5,1.5);
\coordinate (D) at (0,1.5);
\coordinate (E) at (1,0.8);
\coordinate (F) at (4.5,0.8);
\coordinate (G) at (4.5,2.3);
\coordinate (H) at (1,2.3);
% Explicit faces: ABCD, EFGH, ABFE, BCGF, DCGH, ADHE.
% View exposes front ABCD, right BCGF and top DCGH.
% Hidden edges AE, EF and EH meet the obscured rear-bottom-left vertex E.
\draw (A)--(B)--(C)--(D)--cycle;
\draw (B)--(F)--(G)--(C);
\draw (D)--(H)--(G);
\draw[dashed] (A)--(E)--(F);
\draw[dashed] (E)--(H);
\path (A)--(B) node[midway,below=3mm] {$8.5\text{ cm}$};
\path (A)--(D) node[midway,left=3mm] {$2\text{ cm}$};
\path (B)--(F) node[midway,below right=2mm] {$4\text{ cm}$};
\end{tikzpicture}
[/tikz]
